// Subscript helper for Gasing original notation
function getSubscript(n: number | string): string {
  const map: Record<string, string> = {
    '0': '₀', '1': '₁', '2': '₂', '3': '₃', '4': '₄',
    '5': '₅', '6': '₆', '7': '₇', '8': '₈', '9': '₉'
  };
  return String(n).split('').map(char => map[char] || char).join('');
}

interface NotationNode {
  base: number;
  carry: number;
  isHighlighted?: boolean;
}

interface MergeStep {
  nodes: NotationNode[];
  activeColumnIndex: number;
  dialogue: { speaker: 'Guru' | 'Siswa'; text: string; highlight?: boolean }[];
  description: string;
}

function getFormattedNotation(nodes: { base: number; carry: number }[]): string {
  const sups = "⁰¹²³⁴⁵⁶⁷⁸⁹";
  return nodes.map(n => {
    const carryStr = n.carry > 0
      ? n.carry.toString().split('').map((digit: string) => sups[parseInt(digit)] || digit).join('')
      : '';
    return n.base.toString() + carryStr;
  }).join('');
}

function generateMergeSteps(columns: { totalSlashes: number; finalSisa: number }[]): MergeStep[] {
  const steps: MergeStep[] = [];
  const N = columns.length;

  // 1. Build initial nodes
  const nodes: NotationNode[] = [];
  if (columns[0] && columns[0].totalSlashes > 0) {
    nodes.push({ base: columns[0].totalSlashes, carry: 0 });
  }
  for (let cIdx = 0; cIdx < N; cIdx++) {
    const colMeta = columns[cIdx];
    const base = colMeta.finalSisa;
    const nextCol = columns[cIdx + 1];
    const carry = nextCol && nextCol.totalSlashes > 0
      ? nextCol.totalSlashes
      : 0;

    nodes.push({ base, carry });
  }

  // Copy nodes to modify them
  let currentNodes = nodes.map(n => ({ ...n }));

  // First pass: Process each column node from left to right
  for (let i = 0; i < currentNodes.length; i++) {
    const node = currentNodes[i];
    const baseVal = node.base;
    const carryVal = node.carry;
    const sum = baseVal + carryVal;

    const startIndex = (columns[0] && columns[0].totalSlashes > 0) ? 1 : 0;
    if (i < startIndex) continue;

    const stepNodesBefore = currentNodes.map(n => ({ ...n }));
    let updatedNodes = currentNodes.map(n => ({ ...n }));
    let dialogue: { speaker: 'Guru' | 'Siswa'; text: string; highlight?: boolean }[] = [];
    let description = "";

    const sumText = sum.toString();

    dialogue.push({ speaker: 'Guru', text: `${baseVal} tambah ${carryVal}?` });
    dialogue.push({ speaker: 'Siswa', text: `${sumText}.`, highlight: true });

    if (sum >= 10 && i > 0) {
      const units = sum % 10;
      const tens = Math.floor(sum / 10);
      dialogue.push({ speaker: 'Guru', text: `Tulis ${units}, simpan ${tens}.` });
      
      updatedNodes[i].base = units;
      updatedNodes[i].carry = 0; // consumed
      updatedNodes[i - 1].carry = (updatedNodes[i - 1].carry || 0) + tens;
      description = `${baseVal} + ${carryVal} = ${sum}. Tulis ${units} di kolom ini, simpan ${tens} sebagai angka kecil di kolom sebelah kiri.`;
    } else {
      updatedNodes[i].base = sum;
      updatedNodes[i].carry = 0; // consumed
      description = `${baseVal} + ${carryVal} = ${sum}.`;
    }

    const nodesToRender = stepNodesBefore.map((n, idx) => ({
      ...n,
      isHighlighted: idx === i
    }));

    steps.push({
      nodes: nodesToRender,
      activeColumnIndex: i,
      dialogue,
      description
    });

    currentNodes = updatedNodes;
  }

  // Second pass: Process any remaining carries (secondary carries)
  let hasCarries = currentNodes.some(n => n.carry > 0);
  let limit = 0;
  while (hasCarries && limit < 15) {
    limit++;
    const i = currentNodes.findIndex(n => n.carry > 0);
    if (i === -1) break;

    const node = currentNodes[i];
    const baseVal = node.base;
    const carryVal = node.carry;
    const sum = baseVal + carryVal;

    const stepNodesBefore = currentNodes.map(n => ({ ...n }));
    let updatedNodes = currentNodes.map(n => ({ ...n }));
    let dialogue: { speaker: 'Guru' | 'Siswa'; text: string; highlight?: boolean }[] = [];
    let description = "";

    dialogue.push({ speaker: 'Guru', text: `Masih ada angka kecil di atas. ${baseVal} tambah ${carryVal}?` });
    dialogue.push({ speaker: 'Siswa', text: `${sum.toString()}.`, highlight: true });

    if (sum >= 10 && i > 0) {
      const units = sum % 10;
      const tens = Math.floor(sum / 10);
      dialogue.push({ speaker: 'Guru', text: `Tulis ${units}, simpan ${tens}.` });
      
      updatedNodes[i].base = units;
      updatedNodes[i].carry = 0;
      updatedNodes[i - 1].carry = (updatedNodes[i - 1].carry || 0) + tens;
      description = `Gabungkan angka kecil sekunder: ${baseVal} + ${carryVal} = ${sum}. Tulis ${units} di kolom ini, simpan ${tens} di kolom sebelah kiri.`;
    } else {
      updatedNodes[i].base = sum;
      updatedNodes[i].carry = 0;
      description = `Gabungkan angka kecil sekunder: ${baseVal} + ${carryVal} = ${sum}.`;
    }

    const nodesToRender = stepNodesBefore.map((n, idx) => ({
      ...n,
      isHighlighted: idx === i
    }));

    steps.push({
      nodes: nodesToRender,
      activeColumnIndex: i,
      dialogue,
      description
    });

    currentNodes = updatedNodes;
    hasCarries = currentNodes.some(n => n.carry > 0);
  }

  // Final step
  const finalNodes = currentNodes.map(n => ({ ...n, carry: 0, isHighlighted: false }));
  const finalSumStr = finalNodes.map(n => n.base).join('');
  steps.push({
    nodes: finalNodes,
    activeColumnIndex: -1,
    dialogue: [
      { speaker: 'Guru', text: "Hasil akhirnya?" },
      { speaker: 'Siswa', text: `${finalSumStr}.`, highlight: true }
    ],
    description: `Semua angka kecil telah digabungkan. Hasil akhir adalah ${finalSumStr}.`
  });

  return steps;
}

// Gasing Card system component for consistent place value visuals
function GasingPVCard({ type, isCrossed, highlighted }: { type: 'PRB' | 'RB' | 'R' | 'P' | 'S' | string; isCrossed?: boolean; highlighted?: boolean; key?: any }) {
  let colorClasses = "bg-slate-800 border-slate-600 text-slate-300";
  if (type === 'PRB') colorClasses = "bg-violet-950/45 border-violet-500/50 text-violet-300 shadow-violet-950/40";
  else if (type === 'RB') colorClasses = "bg-pink-950/45 border-pink-500/50 text-pink-300 shadow-pink-950/40";
  else if (type === 'R') colorClasses = "bg-indigo-950/45 border-indigo-500/50 text-indigo-300 shadow-indigo-950/40";
  else if (type === 'P') colorClasses = "bg-emerald-950/45 border-emerald-500/50 text-emerald-300 shadow-emerald-950/40";
  else if (type === 'S') colorClasses = "bg-amber-950/45 border-amber-500/50 text-amber-300 shadow-amber-950/40";

  return (
    <div className={`relative w-8 h-8 rounded-lg border-2 font-black text-xs flex items-center justify-center shadow-md select-none transition-all ${colorClasses} ${highlighted ? 'ring-2 ring-indigo-400 border-indigo-300 scale-105' : ''} ${isCrossed ? 'opacity-40 scale-95' : ''}`}>
      {type}
      {isCrossed && (
        <svg className="absolute inset-0 w-full h-full text-rose-500" viewBox="0 0 100 100" preserveAspectRatio="none">
          <line x1="0" y1="100" x2="100" y2="0" stroke="currentColor" strokeWidth="3" />
          <line x1="0" y1="0" x2="100" y2="100" stroke="currentColor" strokeWidth="3" />
        </svg>
      )}
    </div>
  );
}

// Helper function to chunk array into groups of fixed size
function chunkArray<T>(arr: T[], size: number): T[][] {
  const chunks: T[][] = [];
  for (let i = 0; i < arr.length; i += size) {
    chunks.push(arr.slice(i, i + size));
  }
  return chunks;
}

// Global Pola 5 Grouping Component
interface GasingPola5GroupProps {
  type?: string;
  count: number;
  crossedCount?: number;
  highlighted?: boolean | ((idx: number) => boolean);
  highlightLastCardOnly?: boolean;
}

function GasingPola5Group({
  type = 'S',
  count,
  crossedCount = 0,
  highlighted = false,
  highlightLastCardOnly = false
}: GasingPola5GroupProps) {
  if (count <= 0 && crossedCount <= 0) {
    return <span className="text-[10px] text-slate-500 italic block text-center w-full">Kosong</span>;
  }

  const cards: { isCrossed: boolean; originalIndex: number }[] = [];
  for (let i = 0; i < crossedCount; i++) {
    cards.push({ isCrossed: true, originalIndex: i });
  }
  for (let i = 0; i < count; i++) {
    cards.push({ isCrossed: false, originalIndex: crossedCount + i });
  }

  const rows = chunkArray(cards, 5);
  return (
    <div className="flex flex-col gap-1.5 items-start justify-start">
      {rows.map((row, rIdx) => (
        <div key={`row-${rIdx}`} className="flex gap-1.5 justify-start">
          {row.map((card) => {
            const isLast = card.originalIndex === cards.length - 1;
            let isHighlighted = false;
            if (typeof highlighted === 'function') {
              isHighlighted = highlighted(card.originalIndex);
            } else if (highlightLastCardOnly) {
              isHighlighted = isLast;
            } else {
              isHighlighted = highlighted;
            }

            return (
              <GasingPVCard
                key={`card-${card.originalIndex}`}
                type={type}
                isCrossed={card.isCrossed}
                highlighted={isHighlighted}
              />
            );
          })}
        </div>
      ))}
    </div>
  );
}

function renderGasingCards(type: string, count: number, crossedCount = 0) {
  if (type === 'S') {
    return <GasingPola5Group type="S" count={count} crossedCount={crossedCount} />;
  }

  if (count <= 0 && crossedCount <= 0) {
    return <span className="text-[10px] text-slate-500 italic block">Kosong</span>;
  }
  return (
    <div className="flex flex-wrap gap-1.5 items-center justify-center max-w-full">
      {Array.from({ length: crossedCount }).map((_, idx) => (
        <GasingPVCard key={`crossed-${idx}`} type={type} isCrossed={true} />
      ))}
      {Array.from({ length: count }).map((_, idx) => (
        <GasingPVCard key={`normal-${idx}`} type={type} />
      ))}
    </div>
  );
}

// Generate Gasing repeated addition string
function makeRepeatedAdd(groups: number, size: number): string {
  if (groups <= 0) return '0';
  if (groups > 12) {
    return `${size} + ${size} + ... (${groups} kali)`;
  }
  return Array(groups).fill(size).join(' + ');
}

