  const [k4Subtrahend, setK4Subtrahend] = useState<number>(6);

  // States for K5 subtraction
  const [k5A, setK5A] = useState<number>(15);
  const [k5B, setK5B] = useState<number>(7);

  // States for K6 subtraction
  const [k6A, setK6A] = useState<number>(36);
  const [k6B, setK6B] = useState<number>(18);

  // States for K7 subtraction
  const [k7A, setK7A] = useState<number>(236);
  const [k7B, setK7B] = useState<number>(128);

  // States for K8 subtraction
  const [k8A, setK8A] = useState<number>(4236);
  const [k8B, setK8B] = useState<number>(1588);

  // States for Gasing Pembagian (B1 - B6)
  const [b1A, setB1A] = useState<number>(24);
  const [b1B, setB1B] = useState<number>(8);
  const [b1C, setB1C] = useState<number>(3);
  const [b1Format, setB1Format] = useState<'b_x_box' | 'box_x_b'>('b_x_box');

  const [b2A, setB2A] = useState<number>(6);
  const [b2B, setB2B] = useState<number>(2);

  const [b3A, setB3A] = useState<number>(78);
  const [b3B, setB3B] = useState<number>(2);

  const [b4A, setB4A] = useState<number>(7);
  const [b4B, setB4B] = useState<number>(2);
  const [b4CardDistributed, setB4CardDistributed] = useState<number>(0);
  const [b4IsPlaying, setB4IsPlaying] = useState<boolean>(false);

  // Step-by-step teacher pointing animation inside the active column of P12
  useEffect(() => {
    const isPenjumlahanBersusunBanyak = operation === 'penjumlahan' && materialId === 'P12';
    if (!isPenjumlahanBersusunBanyak) return;

    const ex = p12Examples[selectedExample] || p12Examples[0];
    const numCols = ex.columns.length;

    if (stepIndex < numCols) {
      setP12ActiveRowIndex(0);
      const interval = setInterval(() => {
        setP12ActiveRowIndex(prev => {
          const activeCol = ex.columns[stepIndex];
          if (activeCol) {
            if (prev < activeCol.digits.length - 1) {
              return prev + 1;
            } else {
              clearInterval(interval);
            }
          }
          return prev;
        });
      }, 1500);
      return () => clearInterval(interval);
    }
  }, [stepIndex, materialId, selectedExample, operation]);

  useEffect(() => {
    setB4CardDistributed(0);
    setB4IsPlaying(false);
  }, [b4A, b4B, stepIndex]);

  useEffect(() => {
    let intervalId: any = null;
    if (b4IsPlaying && stepIndex === 1) {
      const share = Math.floor(b4A / b4B);
      const target = share * b4B;
      if (b4CardDistributed < target) {
        intervalId = setInterval(() => {
          setB4CardDistributed(prev => {
            if (prev < target) {
              return prev + 1;
            } else {
              setB4IsPlaying(false);
              return prev;
            }
          });
        }, 600);
      } else {
        setB4IsPlaying(false);
      }
    }
    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [b4IsPlaying, b4CardDistributed, b4A, b4B, stepIndex]);

  const [b5A, setB5A] = useState<number>(73);
  const [b5B, setB5B] = useState<number>(4);
  const [b5CardDistributed, setB5CardDistributed] = useState<number>(0);
  const [b5IsPlaying, setB5IsPlaying] = useState<boolean>(false);

  useEffect(() => {
    setB5CardDistributed(0);
    setB5IsPlaying(false);
  }, [b5A, b5B, stepIndex]);

  useEffect(() => {
    let intervalId: any = null;
    const digits = String(b5A).split('').map(Number);
    const N = digits.length;
    const stageIndex = Math.floor(stepIndex / 3);
    const subStep = stepIndex % 3;

    if (b5IsPlaying && subStep === 1 && stageIndex < N) {
      let currentCarry = 0;
      let target = 0;
      for (let i = 0; i <= stageIndex; i++) {
        const combined = currentCarry * 10 + digits[i];
        const res = Math.floor(combined / b5B);
        const rem = combined % b5B;
        if (i === stageIndex) {
          target = res * b5B;
        }
        currentCarry = rem;
      }

      if (b5CardDistributed < target) {
        intervalId = setInterval(() => {
          setB5CardDistributed(prev => {
            if (prev < target) {
              return prev + 1;
            } else {
              setB5IsPlaying(false);
              return prev;
            }
          });
        }, 400);
      } else {
        setB5IsPlaying(false);
      }
    }
    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [b5IsPlaying, b5CardDistributed, b5A, b5B, stepIndex]);

  const [b6A, setB6A] = useState<number>(156);
  const [b6B, setB6B] = useState<number>(12);

  // Dynamic Dialogue Generator for P11 System Coret
  const getP11Dialogue = (numbers: number[], stepIdx: number) => {
    const lines: { speaker: 'Guru' | 'Siswa'; text: string; highlight?: boolean }[] = [];
    
    if (stepIdx === 0) {
      lines.push({ speaker: 'Guru', text: "Mulai dari angka pertama." });
      lines.push({ speaker: 'Siswa', text: `"${numbers[0]}."`, highlight: true });
    } else {
      let currentSum = numbers[0];
      
      for (let i = 1; i <= stepIdx; i++) {
        if (i === stepIdx) {
          const prevSum = currentSum;
          const nextVal = numbers[i];
          const tempSum = prevSum + nextVal;
          
          lines.push({ speaker: 'Guru', text: `Tambah ${nextVal}?` });
          lines.push({ speaker: 'Siswa', text: `"${tempSum}."`, highlight: true });
          
          if (tempSum >= 10) {
            lines.push({ speaker: 'Guru', text: "Adakah yang bisa dicoret?" });
            lines.push({ speaker: 'Siswa', text: "Ada." });
            lines.push({ speaker: 'Guru', text: `Coret ${nextVal}.` });
            lines.push({ speaker: 'Guru', text: "Berapa yang diingat?" });
            lines.push({ speaker: 'Siswa', text: `"${tempSum % 10}."`, highlight: true });
            currentSum = tempSum % 10;
          } else {
            currentSum = tempSum;
          }
        } else {
          const prevSum = currentSum;
          const nextVal = numbers[i];
          const tempSum = prevSum + nextVal;
          if (tempSum >= 10) {
            currentSum = tempSum % 10;
          } else {
            currentSum = tempSum;
          }
        }
      }
    }
    
    if (stepIdx === numbers.length) {
      let slashesCount = 0;
      let runningSum = numbers[0];
      for (let i = 1; i < numbers.length; i++) {
        const temp = runningSum + numbers[i];
        if (temp >= 10) {
          slashesCount++;
          runningSum = temp % 10;
        } else {
          runningSum = temp;
        }
      }
      
      lines.push({ speaker: 'Guru', text: "Berapa banyak coretan?" });
      lines.push({ speaker: 'Siswa', text: `"${slashesCount}."`, highlight: true });
      lines.push({ speaker: 'Guru', text: "Sisa satuan akhir?" });
      lines.push({ speaker: 'Siswa', text: `"${runningSum}."`, highlight: true });
      lines.push({ speaker: 'Guru', text: "Jadi hasil akhirnya?" });
      lines.push({ speaker: 'Siswa', text: `"${slashesCount}${runningSum}!"`, highlight: true });
    }
    
    return lines;
  };

  const getNotasiGasingText = (ex: any) => {
    let parts = [];
    const firstVal = ex.columns[0].totalSlashes * 10 + ex.columns[0].finalSisa;
    parts.push(firstVal.toString());
    for (let i = 1; i < ex.columns.length; i++) {
      const carry = ex.columns[i].totalSlashes;
      if (carry > 0) {
        const sups = "⁰¹²³⁴⁵⁶⁷⁸⁹";
        const carryStr = carry.toString().split('').map((digit: string) => sups[parseInt(digit)] || digit).join('');
        parts[parts.length - 1] += carryStr;
      }
      parts.push(ex.columns[i].finalSisa.toString());
    }
    return parts.join('');
  };

  const getP12Dialogue = (ex: any, stepIdx: number) => {
    const numCols = ex.columns.length;
    const lines: { speaker: 'Guru' | 'Siswa'; text: string; highlight?: boolean }[] = [];

    if (stepIdx < numCols) {
      const col = ex.columns[stepIdx];
      const digits = col.digits;

      if (stepIdx === 0) {
        lines.push({ speaker: 'Guru', text: "Kerjakan dari depan." });
      } else {
        lines.push({ speaker: 'Guru', text: "Kolom berikutnya." });
      }

      if (digits.length > 0) {
        let currentSum = digits[0];
        const hasAnySlash = col.totalSlashes > 0;

        if (!hasAnySlash) {
          let sumStr = `${digits[0]}`;
          let temp = digits[0];
          for (let i = 1; i < digits.length; i++) {
            sumStr += ` + ${digits[i]}`;
            temp += digits[i];
          }
          lines.push({ speaker: 'Guru', text: `${digits[0]} tambah ${digits[1]}?` });
          lines.push({ speaker: 'Siswa', text: `${temp}.`, highlight: true });
        } else {
          const d1 = digits[0];
          const d2 = digits[1];
          lines.push({ speaker: 'Guru', text: `${d1} tambah ${d2}?` });
          let sum = d1 + d2;
          lines.push({ speaker: 'Siswa', text: `${sum}.` });
          
          if (sum >= 10) {
            lines.push({ speaker: 'Guru', text: "Mana yang dicoret?" });
            lines.push({ speaker: 'Siswa', text: `${d2}.` });
            lines.push({ speaker: 'Guru', text: "Yang diingat?" });
            lines.push({ speaker: 'Siswa', text: `${sum % 10}.`, highlight: true });
            currentSum = sum % 10;
          } else {
            currentSum = sum;
          }

          for (let i = 2; i < digits.length; i++) {
            const nextVal = digits[i];
            lines.push({ speaker: 'Guru', text: `${currentSum} tambah ${nextVal}?` });
            let tempSum = currentSum + nextVal;
            lines.push({ speaker: 'Siswa', text: `${tempSum}.` });

            if (tempSum >= 10) {
              lines.push({ speaker: 'Guru', text: "Mana yang dicoret?" });
              lines.push({ speaker: 'Siswa', text: `${nextVal}.` });
              lines.push({ speaker: 'Guru', text: "Yang diingat?" });
              lines.push({ speaker: 'Siswa', text: `${tempSum % 10}.`, highlight: true });
              currentSum = tempSum % 10;
            } else {
              currentSum = tempSum;
            }
          }
        }

        lines.push({ speaker: 'Guru', text: "Ada berapa yang dicoret?" });
        lines.push({ speaker: 'Siswa', text: `${col.totalSlashes}.` });

        if (stepIdx === 0) {
          const firstColVal = col.totalSlashes * 10 + col.finalSisa;
          lines.push({ speaker: 'Guru', text: "Kolom depan hasilnya?" });
          lines.push({ speaker: 'Siswa', text: `${firstColVal}.`, highlight: true });
        } else {
          lines.push({ speaker: 'Guru', text: "Kolom ini hasilnya?" });
          lines.push({ speaker: 'Siswa', text: `${col.finalSisa}.`, highlight: true });
        }
      }
    } else if (stepIdx === numCols) {
      // Step 3: Notasi Gasing Akhir
      lines.push({ speaker: 'Guru', text: "Sekarang tulis Notasi Gasing yang lengkap." });
      const notasiText = getNotasiGasingText(ex);
      lines.push({ speaker: 'Guru', text: "Bagaimana Notasi Gasing yang sudah terbentuk?" });
      lines.push({ speaker: 'Siswa', text: `${notasiText}.`, highlight: true });
    } else if (stepIdx > numCols) {
      // Step 4+: Gabungkan Angka Kecil (Dynamic Substeps)
      const mergeSteps = generateMergeSteps(ex.columns);
      const mIdx = stepIdx - (numCols + 1);
      if (mergeSteps[mIdx]) {
        lines.push(...mergeSteps[mIdx].dialogue);
      }
    }

    return lines;
  };

  const generateNewPractice = () => {
    let a = 0;
    let b = 0;
    let attempts = 0;
    const maxAttempts = 500;

    while (attempts < maxAttempts) {
      // 1. Operand Pertama: Wajib 3 digit (100 - 999)
      a = Math.floor(Math.random() * 900) + 100;

      // 2. Operand Kedua: Sesuai Materi
      if (materialId === 'X20') {
        b = Math.floor(Math.random() * 8) + 2; // 1 digit (2 - 9)
      } else if (materialId === 'X21') {
        b = Math.floor(Math.random() * 90) + 10; // 2 digit (10 - 99)
      } else if (materialId === 'X22') {
        b = Math.floor(Math.random() * 900) + 100; // 3 digit (100 - 999)
      } else {
        b = Math.floor(Math.random() * 8) + 2; // Fallback
      }

      // VALIDASI WAJIB:
      const aString = a.toString();
      const bString = b.toString();

      const isAValid = aString.length === 3;
      let isBValid = false;
      let expectedGroups = 0;

      if (materialId === 'X20') {
        isBValid = bString.length === 1;
        expectedGroups = 3;
      } else if (materialId === 'X21') {
        isBValid = bString.length === 2;
        expectedGroups = 4;
      } else if (materialId === 'X22') {
        isBValid = bString.length === 3;
        expectedGroups = 5;
      } else {
        isBValid = true; // Fallback
        expectedGroups = 0;
      }

      // VALIDASI PEMBAHASAN: Jumlah kelompok hasil harus sesuai materi.
      let actualGroups = 0;
      if (materialId === 'X20') {
        actualGroups = 3;
      } else if (materialId === 'X21') {
        actualGroups = 4;
      } else if (materialId === 'X22') {
        actualGroups = 5;
      }

      // Pastikan kedua operand dan pembahasan tivalidasi dengan sempurna
      if (isAValid && isBValid && (expectedGroups === 0 || actualGroups === expectedGroups)) {
        break; // Lolos seluruh validasi Gasing
      }

      attempts++;
    }

    setPracticeA(a);
    setPracticeB(b);
    setPracticeAnswer('');
    setPracticeChecked(null);
    setPracticeShowStep(false);
  };

  useEffect(() => {
    if (materialId === 'X20' || materialId === 'X21' || materialId === 'X22') {
      generateNewPractice();
    }
  }, [materialId]);

  // Custom sandbox for multiplication
  const [customGroups, setCustomGroups] = useState<number>(3);
  const [customSize, setCustomSize] = useState<number>(2);
  const [useCustom, setUseCustom] = useState<boolean>(false);

  // Reset step index if material changes or example changes
  useEffect(() => {
    setStepIndex(0);
    setX14Tab(0);
    if (materialId === 'X20' || materialId === 'X21' || materialId === 'X22' || materialId === 'B6') {
      setViewMode('abstract');
    }
    if (materialId === 'P1') {
      setP12A(3);
      setP12B(2);
      setP12UseCustom(false);
    } else if (materialId === 'P2') {
      setP12A(4);
      setP12B(3);
      setP12UseCustom(false);
    } else if (materialId === 'P3') {
      setP3Value(7);
    } else if (materialId === 'P4') {
      setP4Value(3);
      setP4Revealed([]);
    } else if (materialId === 'P5') {
      setP5A(9);
      setP5B(2);
      setP5Revealed([]);
    }
  }, [materialId, selectedExample]);

  // Synchronize category state for K3 based on the active numbers (whether loaded from presets or custom inputs)
  useEffect(() => {
    if (materialId === 'K3') {
      const activeK3A = k3UseCustom 
        ? k3A 
        : (k3Category === 'tanpa_menukar' 
          ? K3_TANPA_MENUKAR[selectedExample]?.a || 17 
          : K3_DENGAN_MENUKAR[selectedExample]?.a || 12);
      const activeK3B = k3UseCustom 
        ? k3B 
        : (k3Category === 'tanpa_menukar' 
          ? K3_TANPA_MENUKAR[selectedExample]?.b || 4 
          : K3_DENGAN_MENUKAR[selectedExample]?.b || 5);
      
      const isMenukar = (activeK3A % 10) < activeK3B;
      const targetCategory = isMenukar ? 'menukar' : 'tanpa_menukar';
      
      if (k3Category !== targetCategory) {
        setK3Category(targetCategory);
      }
    }
  }, [materialId, k3UseCustom, k3A, k3B, selectedExample, k3Category]);

  // Synchronize state for 2-digit/3-digit multiplier for X12/X13/X14/X15/X16/X17/X18/X19/X20/X21/X22
  useEffect(() => {
    const isX12X13Active = materialId === 'X12' || materialId === 'X13';
    const isX14X15X16Active = materialId === 'X14' || materialId === 'X15' || materialId === 'X16' || materialId === 'X17' || materialId === 'X18' || materialId === 'X19';
    const isX20_X22_Active = materialId === 'X20' || materialId === 'X21' || materialId === 'X22';
    
    if (isX12X13Active) {
      if (customGroups < 10 || customGroups > 99) {
        setCustomGroups(24);
      }
      if (customSize > 9) {
        setCustomSize(6);
      }
    } else if (isX14X15X16Active) {
      if (materialId === 'X17') {
        if (customGroups < 90 || customGroups > 99) {
          setCustomGroups(95);
        }
        if (customSize < 90 || customSize > 99) {
          setCustomSize(96);
        }
      } else if (materialId === 'X18') {
        if (customGroups < 46 || customGroups > 55) {
          setCustomGroups(52);
        }
        if (customSize < 46 || customSize > 55) {
          setCustomSize(54);
        }
      } else if (materialId === 'X19') {
        if (customGroups % 10 !== 0 || customGroups < 10 || customGroups > 90) {
          setCustomGroups(30);
        }
        if (customSize % 10 !== 0 || customSize < 10 || customSize > 90) {
          setCustomSize(40);
        }
      } else {
        if (customGroups < 11 || customGroups > 99) {
          setCustomGroups(12);
        }
        if (customSize < 11 || customSize > 99) {
          setCustomSize(15);
        }
      }
    } else if (isX20_X22_Active) {
      if (customGroups < 100 || customGroups > 999) {
        setCustomGroups(123);
      }
      if (materialId === 'X20') {
        if (customSize < 1 || customSize > 9) {
          setCustomSize(3);
        }
      } else if (materialId === 'X21') {
        if (customSize < 10 || customSize > 99) {
          setCustomSize(12);
        }
      } else if (materialId === 'X22') {
        if (customSize < 100 || customSize > 999) {
          setCustomSize(321);
        }
      }
    } else {
      if (customGroups > 10) {
        setCustomGroups(3);
      }
    }
  }, [materialId]);

  // General check for the target materials
  const isPenjumlahan = operation === 'PENJUMLAHAN';
  const isPengurangan = operation === 'PENGURANGAN';
  const isPerkalian = operation === 'PERKALIAN';
  const isPembagian = operation === 'PEMBAGIAN';

  // Helper selectors
  const isPasangan10 = isPenjumlahan && materialId === 'P3';
  const isPenjumlahanDasar = isPenjumlahan && (materialId === 'P1' || materialId === 'P2');
  const isPenjumlahanP4 = isPenjumlahan && materialId === 'P4';
  const isPenjumlahanJembatan = isPenjumlahan && materialId === 'P5';
  const isPenjumlahanP6 = isPenjumlahan && materialId === 'P6';
  const isPenjumlahanP7 = isPenjumlahan && materialId === 'P7';
  const isPenjumlahanDuaSatu = isPenjumlahanP6 || isPenjumlahanP7;
  const isPenjumlahanDuaDua = isPenjumlahan && materialId === 'P8';
  const isPenjumlahanBersusun = isPenjumlahan && materialId === 'P9';
  const isPenjumlahanP10 = isPenjumlahan && materialId === 'P10';
  const isPenjumlahanCoret = isPenjumlahan && materialId === 'P11';
  const isPenjumlahanBersusunBanyak = isPenjumlahan && materialId === 'P12';
  const isPenjumlahanDuaAngka = isPenjumlahanDuaSatu || isPenjumlahanDuaDua || isPenjumlahanBersusun || isPenjumlahanP10;
  const isK1orK2 = isPengurangan && (materialId === 'K1' || materialId === 'K2');
  const isPenguranganK3 = isPengurangan && materialId === 'K3';
  const isPenguranganDasar = isPengurangan && materialId === 'K4';
  const isPenguranganPasangan = isPengurangan && materialId === 'K5';
  const isPenguranganK6 = isPengurangan && materialId === 'K6';
  const isPenguranganK7 = isPengurangan && materialId === 'K7';
  const isPenguranganK8 = isPengurangan && materialId === 'K8';
  const isPenguranganDuaAngka = isPengurangan && (materialId === 'K6' || materialId === 'K7' || materialId === 'K8');
  const isPerkalianWadahIsi = isPerkalian && (materialId === 'X3' || materialId === 'X8');
  const isArtiPerkalian = isPerkalian && materialId === 'X0';
  const isPerkalian1 = isPerkalian && materialId === 'X1';
  const isPerkalian9 = isPerkalian && materialId === 'X4';
  const isPerkalianDepan = isPerkalian && (materialId === 'X12' || materialId === 'X13');
  const isX20_X22 = isPerkalian && (materialId === 'X20' || materialId === 'X21' || materialId === 'X22');
  const isX20 = isPerkalian && (materialId === 'X20' || materialId === 'X21' || materialId === 'X22');
  const isX12X13 = isPerkalian && (materialId === 'X12' || materialId === 'X13');
  const isX14X15X16 = isPerkalian && (materialId === 'X14' || materialId === 'X15' || materialId === 'X16' || materialId === 'X17' || materialId === 'X18' || materialId === 'X19');
  const isPerkalianStitch = isPerkalian && (materialId === 'X21' || materialId === 'X22') && false;
  const isMateriPerkalianTabel = isPerkalian && 
    materialId !== 'X0' && 
    materialId !== 'X12' && 
    materialId !== 'X13' && 
    materialId !== 'X14' && 
    materialId !== 'X15' && 
    materialId !== 'X16' &&
    materialId !== 'X17' &&
    materialId !== 'X18' &&
    materialId !== 'X19' &&
    materialId !== 'X20' &&
    materialId !== 'X21' &&
    materialId !== 'X22';
  const isPembagianB1 = isPembagian && materialId === 'B1';
  const isPembagianB2 = isPembagian && materialId === 'B2';
  const isPembagianB3 = isPembagian && materialId === 'B3';
  const isPembagianB4 = isPembagian && materialId === 'B4';
  const isPembagianB5 = isPembagian && materialId === 'B5';
  const isPembagianB6 = isPembagian && materialId === 'B6';
  const isPembagianDepan = isPembagian && (materialId === 'B5' || materialId === 'B6');

  // --- Dynamic Multiplication Helpers / Subcontrollers ---
  const perkalianExs = getPerkalianExamples(materialId);
  const activeEx = perkalianExs[selectedExample] || perkalianExs[0];
  const g = useCustom ? customGroups : activeEx.groups;
  const s = useCustom ? customSize : activeEx.size;
  const subS = getSubscript(s);
  const resultVal = g * s;
