    const totalPAdjusted = totalPRaw + sToPTransfer;
    const pToRTransfer = Math.floor(totalPAdjusted / 10);
    const remainingP = totalPAdjusted % 10;

    const totalRFinal = totalRRaw + pToRTransfer;
    const finalVal = numA * numB;

