      const puluhNeedsExchange = puluhEff < bPuluh;
      const ratusEff = puluhNeedsExchange ? (aRatus - 1) : aRatus;
      const puluhEffFinal = puluhNeedsExchange ? (puluhEff + 10) : puluhEff;

      const ratusRes = ratusEff - bRatus;
      const puluhRes = puluhEffFinal - bPuluh;
      const satuanRes = satuanNeedsExchange ? (10 - bSatuan + aSatuan) : (aSatuan - bSatuan);

      const localStep = Math.min(stepIndex, 5);

