      const bRB = Math.floor(b / 1000);
      const bR = Math.floor((b % 1000) / 100);
      const bP = Math.floor((b % 100) / 10);
      const bS = b % 10;

      // Exchange Flags & remaining values (backward check)
      const sNeedsEx = aS < bS;
      const pEff = sNeedsEx ? (aP - 1) : aP;
      const pNeedsEx = pEff < bP;
      const rEff = pNeedsEx ? (aR - 1) : aR;
      const rNeedsEx = rEff < bR;
      const rbEff = rNeedsEx ? (aRB - 1) : aRB;

      // Effective values for display and math
      const rbFinal = rbEff;
      const rFinal = rNeedsEx ? (rEff + 10) : rEff;
      const pFinal = pNeedsEx ? (pEff + 10) : pEff;
      const sFinal = sNeedsEx ? (aS + 10) : aS;

      // Answers per place value
      const ansTh = rbFinal - bRB;
      const ansHun = rFinal - bR;
      const ansTen = pFinal - bP;
      const ansOne = sFinal - bS;

