      let resultRibuanVal = "";
      let resultRatusanVal = "";
      let resultPuluhanVal = "";
      let resultSatuanVal = "";

      if (localStep >= 3) resultRibuanVal = String(ansTh);
      if (localStep >= 4) resultRatusanVal = String(ansHun);
      if (localStep >= 5) resultPuluhanVal = String(ansTen);
      if (localStep >= 6) resultSatuanVal = String(ansOne);

