    const getBoxCardsCount = (boxIdx: number, step: number) => {
      let count = 0;
      for (let j = 1; j <= step; j++) {
        if (((j - 1) % b) + 1 === boxIdx) {
          count++;
        }
      }
      return count;
    };

    const ordinals = ["pertama", "kedua", "ketiga", "keempat", "kelima", "keenam", "ketujuh", "kedelapan", "kesembilan", "kesepuluh", "kesebelas", "kedua belas", "ketiga belas", "keempat belas", "kelima belas"];
    const currentTargetBox = stepIndex > 0 ? ((stepIndex - 1) % b) + 1 : 0;
    const currentCardOrdinal = stepIndex > 0 ? (ordinals[stepIndex - 1] || `ke-${stepIndex}`) : "";

